// ---------------------------------------------------------------------------
//  Meldung formulieren
// ---------------------------------------------------------------------------
//  Fehler haben zwei Dringlichkeiten. Was einen laufenden Anruf betrifft,
//  muss sofort raus — dort steht gerade jemand am Telefon. Alles andere
//  kann bis morgen früh warten; die Warteschlange hält Unwichtiges nachts
//  ohnehin zurück.

const f = $input.first().json;
const wf   = f.workflow?.name ?? 'unbekannt';
const node = f.execution?.lastNodeExecuted ?? '—';
const text = (f.execution?.error?.message ?? f.execution?.error?.description ?? 'kein Text').slice(0, 400);
const url  = f.execution?.url ?? null;

const waehrendAnruf = /Anruf-Start|Verfügbarkeit|Termin buchen|Notiz/i.test(wf);

const zeilen = [
  `${waehrendAnruf ? '🚨' : '⚠️'} *Voice-Agent: Fehler*`,
  '',
  `Workflow: *${wf}*`,
  `Node: ${node}`,
  '',
  '```',
  text,
  '```',
];

if (waehrendAnruf) {
  zeilen.push('', '_Das betrifft laufende Anrufe. Der Agent nimmt weiter ab, aber ohne_',
              '_Kalender und ohne Durchstellen. Prüfen: `make status`_');
}
if (url) zeilen.push('', url);

return [{ json: {
  text: zeilen.join('\n'),
  anlass: 'fehler',
  dringlichkeit: waehrendAnruf ? 5 : 3,
} }];
